async function (variables) {
    var userOnboardingAdminGrid = new GridWidget(variables.element, variables.dataSource);
    userOnboardingAdminGrid.columns = [
        { field: "State", type: "string", title: "[resource_shortdisplayname[requestState]]", template: function (data) { return "<span class='k-icon " + (UserOnboardingAdmin.iconStates[data.State]) + "'></span>"; } },
        { field: "email", type: "string", title: "[resource_shortdisplayname[userEmail]]", template: function (data) { return "" + (JSON.parse(data.DataJson).fields[0].email) + ""; } },
        { field: "companyName", type: "string", title: "[resource_shortdisplayname[companyName]]", template: function (data) { return "" + (JSON.parse(data.DataJson).fields[1].companyName) + ""; } },
        { field: "CreatedOn", type: "date", title: "[resource_shortdisplayname[requestDate]]", format: "{0:" + type.dateFormat + "}" },
        { field: "CreatedBy", title: "[resource_shortdisplayname[CreatedBy]]" },
        { field: "requestType", type: "string", title: "[resource_shortdisplayname[requestType]]", template: function (data) { return "" + (JSON.parse(data.DataJson).fields[2].requestType ? UserOnboardingAdmin.requestTypes[JSON.parse(data.DataJson).fields[2].requestType.value] : '') + ""; } },
    ];
    userOnboardingAdminGrid.editable = false;
    userOnboardingAdminGrid.sortable = false;
    userOnboardingAdminGrid.filterable = false;
    userOnboardingAdminGrid.pageable = false;
    userOnboardingAdminGrid.groupable = false;
    userOnboardingAdminGrid.scrollable = false;
    userOnboardingAdminGrid.toolbar = "<button name='addUserOnboardingRequest'><span class='k-icon k-i-plus'></span>[resource_displayname[New]]</button>";
    variables.UserOnboardingAdminGrid = userOnboardingAdminGrid;
    return userOnboardingAdminGrid;
}
